import { RendererCanvas } from './base/RendererCanvas';

export class Solution extends RendererCanvas {
	v0;
	t = 0.0;
	constructor(id: string) {
		super(document.getElementById(id) as HTMLDivElement);
		this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
		this.init();
	}
	public init() {
		this.v0 = new Particle(10, 10, 10);
		this.start();
	}
	public render(ctx: CanvasRenderingContext2D): void {
		// const v0 = new Particle(0, 0, 0);
		// v0.render(ctx);

		// const v1 = new Vector3(0, 100, 0);
		// v1.render(ctx);

		// const v2 = new Vector3(100, 0, 0);
		// v2.render(ctx);

		this.v0.render(ctx, this.t);

		this.t += 0.1;
		// console.log(this.t)
	}
}

class Particle {
	public p: Vector3 = new Vector3(0.0, 0.0, 0.0);
	public u: Vector3 = new Vector3(10.0, 5.0, 3.0);
	public f: Vector3 = new Vector3(0.0, 0.0, 0.0);
	public m: number = 0.1;
	public damping: number = 0.9;
	public constructor(x: number = 0, y: number = 0, z: number = 0) {
		this.p.x = x;
		this.p.y = y;
		this.p.z = z;
	}
	public render(ctx, dt: number) {
		this.move(dt);
		this.p.render(ctx);
	}
	public move(dt: number) {
		// u *= damping;
		this.u.x = this.u.x * this.damping;
		this.u.y = this.u.y * this.damping;
		this.u.z = this.u.z * this.damping;

		// u += f * (dt / this.m);
		this.u.x = this.u.x + (this.f.x * dt) / this.m;
		this.u.y = this.u.y + (this.f.y * dt) / this.m;
		this.u.z = this.u.z + (this.f.z * dt) / this.m;

		// u += new Vector3(0, 0, -0.98);
		this.u.z += -0.98;

		// p += u * dt;
		this.p.x = this.p.x + this.u.x * dt;
		this.p.y = this.p.y + this.u.y * dt;
		this.p.z = this.p.z + this.u.z * dt;

		if (this.p.z < 0.0) {
			this.p.z = 0.0;
			if (this.u.z < 0.0) this.u.z = -this.u.z;
		}
	}
}

class Vector3 {
	public x: number = 0.0;
	public y: number = 0.0;
	public z: number = 0.0;
	public r: number = 5;
	constructor(x, y, z) {
		this.x = x;
		this.y = y;
		this.z = z;
	}
	public render(ctx: CanvasRenderingContext2D) {
		ctx.fillStyle = '#333';
		ctx.beginPath();
		ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2.0);
		ctx.closePath();
		ctx.fill();
	}
}

